const insertDueNotices = `-- name: InsertDueNotices :many
INSERT INTO banquet_notices (tenant_id, property_id, user_id, kind, event_id, notice_date)
SELECT e.tenant_id, e.property_id, e.sales_user_id, 'OPTION_DUE', e.id, $1::date
FROM banquet_events e
WHERE e.tenant_id = $2 AND e.property_id = $3 AND e.status = 'TENTATIVE' AND e.option_until <= $1::date
ON CONFLICT (property_id, event_id, user_id, notice_date) WHERE kind = 'OPTION_DUE' DO NOTHING
RETURNING event_id
`

type InsertDueNoticesParams struct {
	NoticeDate civil.Date
	TenantID   int64
	PropertyID int64
}

// The day close: one reminder for each tentative event whose option date has come, once for the event, the salesperson and the day.
func (q *Queries) InsertDueNotices(ctx context.Context, arg InsertDueNoticesParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, insertDueNotices, arg.NoticeDate, arg.TenantID, arg.PropertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var event_id int64
		if err := rows.Scan(&event_id); err != nil {
			return nil, err
		}
		items = append(items, event_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

